// SecurityFeatureCodePtrFromProto is SecurityFeatureCodeFromProto for nullable columns:
// unspecified maps to nil.
func SecurityFeatureCodePtrFromProto(v codes.SecurityFeatureCode) *SecurityFeatureCode {
	if s := SecurityFeatureCodeFromProto(v); s != "" {
		return &s
	}
	return nil
}

// SecurityFeatureCodePtrToProto is SecurityFeatureCodeToProto for nullable columns.
func SecurityFeatureCodePtrToProto(v *SecurityFeatureCode) codes.SecurityFeatureCode {
	if v == nil {
		return 0
	}
	return SecurityFeatureCodeToProto(*v)
}

