func DateOrMonthDayToProto(m *DateOrMonthDay) *types.DateOrMonthDay {
	if m == nil {
		return nil
	}
	out := &types.DateOrMonthDay{}
	if v := fromPtr(m.MonthDay); v != "" {
		out.Value = &types.DateOrMonthDay_MonthDay{MonthDay: v}
	}
	if v := DateToProto(m.Day); v != nil {
		out.Value = &types.DateOrMonthDay_Day{Day: v}
	}
	return out
}

// DateOrMonthDayFromProto maps the proto message's data fields onto a fresh row.
// It never invents keys or relations: primary keys, resource references, and
